(()=>{let init={};try{if(window.name.startsWith('whole-platform:'))init=JSON.parse(window.name.slice(15));}catch{}const token=new URLSearchParams(location.search).get('whole_review_token');if(token){try{const cached=JSON.parse(sessionStorage.getItem('whole-platform-frame-init')||'null');init=cached?.token===token?cached:{token,initialized:false};}catch{init={token,initialized:false};}}window.WholeInit=init;window.name='';const prefix='finsyndeo-whole-review-';try{if(location.pathname.includes('/application/')){const role=location.pathname.includes('Institution-apply')?'provider':'applicant';sessionStorage.setItem(prefix+'preview-session',JSON.stringify({role,email:init.email||role+'@review.example'}));const key=prefix+(role==='provider'?'provider-draft-v1':'unified-draft-v1');let newest=null;try{newest=JSON.parse(localStorage.getItem(key)||'null');}catch{}const sameCase=role==='applicant'&&init.initialized&&init.caseId&&newest?.caseId===init.caseId;const localIsNewer=sameCase&&newest?.savedAt&&(!init.draft?.savedAt||(typeof newest.savedAt==='number'?newest.savedAt:Date.parse(newest.savedAt))>(typeof init.draft.savedAt==='number'?init.draft.savedAt:Date.parse(init.draft.savedAt)));if(init.draft&&!localIsNewer)localStorage.setItem(key,JSON.stringify(init.draft));else if(init.fresh&&!localIsNewer&&init.initialized)localStorage.removeItem(key);}if(location.pathname.includes('/facilities/')&&init.financial){localStorage.setItem(prefix+'platform-walkthrough-v1',JSON.stringify(init.financial));localStorage.setItem(prefix+'platform-walkthrough-v1-ui',JSON.stringify({role:init.role,actor:init.actor,view:init.view||'results',application:init.application,drafts:{},sort:'match',provider:init.provider||'P14'}));}if(location.pathname.includes('/introducer/')&&init.intro)localStorage.setItem(prefix+'introducer-phase1-v1',JSON.stringify({state:init.intro,ui:{role:init.role,view:init.view||'dashboard',intro:init.introId||'I-A',adminIntro:init.introId||'I-A',provider:'FS-003',currency:'EUR',drafts:init.drafts||{}}}));}catch(e){window.WholeInit.storageError=e.message;}})();
